with latest_match as (select s.id, s.customer_id, s.store_id, s.amount, s.discount, s.shipping_fee, latest.shipment_carrier from orders s join lateral (select c.carrier as shipment_carrier from shipments c where c.order_id = s.id order by c.shipped_date desc, c.id desc limit 1) latest on true) select id, customer_id, store_id, amount, discount, shipping_fee, shipment_carrier from latest_match;
